$pdo = db();
$count = default_count_unit($pdo, $id);
?>
<?= view('shared/header.php', ['id' => 'ingredient-site-settings', 'title' => $i['name'] . ' · per site', 'crumbs' => [['Home', '/'], ['Ingredients', '/ingredients/'], [$i['name'], '/ingredients/' . $id], ['Per site', null]], 'back' => back_link() ?? ['/ingredients/' . $id, $i['name']]]) ?>
<div class="main-content" id="ingredient-site-settings-content">
