        <div class="card-body">
            <form method="post" action="/ingredients/sites/save.php" hx-post="/ingredients/sites/save.php" hx-target="#flash" id="<?= $p ?>" class="row g-2 align-items-end">
                <?= csrf_field() ?><input type="hidden" name="ingredient" value="<?= $id ?>"><input type="hidden" name="site" value="<?= $sid ?>">
