                <div class="col-6 col-md-2"><label class="form-label fs-12 text-muted" for="<?= $p ?>-field-par_mode">Mode</label><select name="par_mode" id="<?= $p ?>-field-par_mode" class="form-select btn-touch" <?= $mayWriteHere ? '' : 'disabled' ?>><option value="fixed" <?= $s['par_mode'] === 'fixed' ? 'selected' : '' ?>>Fixed par</option><option value="dynamic" <?= $s['par_mode'] === 'dynamic' ? 'selected' : '' ?>>Dynamic (from the forecast)</option></select></div>
                <div class="col-6 col-md-2"><label class="form-label fs-12 text-muted" for="<?= $p ?>-field-reorder_min">Reorder minimum</label><div class="input-group"><input type="number" step="any" min="0" name="reorder_min" id="<?= $p ?>-field-reorder_min" class="form-control btn-touch" value="<?= e($s['reorder_min_base'] === null ? '' : fmt_input(qty_from_base($pdo, $id, $s['reorder_min_base'], $count ?? $i['base_unit_code']) ?? $s['reorder_min_base'], 2)) ?>" <?= $mayWriteHere ? '' : 'disabled' ?>><select name="reorder_min_unit" id="<?= $p ?>-field-reorder_min_unit" class="form-select btn-touch" <?= $mayWriteHere ? '' : 'disabled' ?>><?php foreach ($options as $o): ?><option value="<?= e($o['code']) ?>" <?= ($count ?? $i['base_unit_code']) === $o['code'] ? 'selected' : '' ?>><?= e($o['code']) ?></option><?php endforeach; ?></select></div></div>
                <div class="col-6 col-md-2"><label class="form-label fs-12 text-muted" for="<?= $p ?>-field-service_level">Service level</label><select name="service_level" id="<?= $p ?>-field-service_level" class="form-select btn-touch" <?= $mayWriteHere ? '' : 'disabled' ?>><?php foreach (SERVICE_LEVELS as $k => $l): ?><option value="<?= $k ?>" <?= (string) $s['service_level'] === $k ? 'selected' : '' ?>><?= $l ?></option><?php endforeach; ?></select></div>
