            <form method="post" action="/ingredients/sites/cost.php" hx-post="/ingredients/sites/cost.php" hx-target="#flash" id="cost-override-form-<?= $sid ?>" class="row g-2 align-items-end mt-2 border-top pt-2">
                <?= csrf_field() ?><input type="hidden" name="ingredient" value="<?= $id ?>"><input type="hidden" name="site" value="<?= $sid ?>">
                <div class="col-6 col-md-3"><label class="form-label fs-12 text-muted" for="cost-override-form-<?= $sid ?>-field-cost">Cost override<?= $s['cost_override_per_base'] !== null ? ' (now $' . e(fmt_num($s['cost_override_per_base'], 6)) . ' / ' . e($i['base_unit_code']) . ')' : '' ?></label><div class="input-group"><span class="input-group-text">$</span><input type="number" step="any" min="0" name="cost" id="cost-override-form-<?= $sid ?>-field-cost" class="form-control btn-touch" placeholder="blank clears"><select name="unit" id="cost-override-form-<?= $sid ?>-field-unit" class="form-select btn-touch"><?php foreach ($options as $o): ?><option value="<?= e($o['code']) ?>" <?= $i['recipe_unit_code'] === $o['code'] ? 'selected' : '' ?>>per <?= e($o['code']) ?></option><?php endforeach; ?></select></div></div>
                <div class="col-6 col-md-5"><label class="form-label fs-12 text-muted" for="cost-override-form-<?= $sid ?>-field-reason">Reason</label><input type="text" name="reason" id="cost-override-form-<?= $sid ?>-field-reason" class="form-control btn-touch" maxlength="200"></div>
                <div class="col-12 col-md-2"><button type="submit" class="btn btn-light btn-touch w-100" id="cost-override-form-<?= $sid ?>-save-btn">Set</button></div>
